import argparse,json,sys
from pathlib import Path
sys.path.insert(0,'scripts');import inspection,capacity
out=Path('artifacts/webtransport')
for repeat in range(1,4):
 for v in (['event-batch','packet-spaces'] if repeat!=2 else ['packet-spaces','event-batch']):
  for case in ['private','roomonly','mixed']:
   a=json.loads((out/f'owner-poll-{case}-owner-poll-1.json').read_text())['args'];a.update(server=str((out/f'binaries/{v}-relay').resolve()),output=str((out/f'packet-spaces-{case}-{v}-{repeat}.json').resolve()))
   for k in ['server','client','client_source_root','tls_front','tls_cert','tls_key','tls_ca','heap_profile','heap_library','output','fanout_latency_output']:
    if a.get(k) is not None:a[k]=Path(a[k])
   r=inspection.run(argparse.Namespace(**a));assert r['passed'];print('COMPARED',case,v,repeat,flush=True)
for v in ['event-batch','packet-spaces']:
 a=json.loads((out/'owner-poll-capacity-owner-poll-1.json').read_text())['args'];a.update(server=str((out/f'binaries/{v}-relay').resolve()),output=str((out/f'packet-spaces-capacity-{v}-1.json').resolve()))
 for k in ['server','client','output','server_preload','user_latency_output','user_latency_histogram_output','pressure_client','kernel_slab_sizes']:
  if a.get(k) is not None:a[k]=Path(a[k])
 capacity.run(argparse.Namespace(**a));print('CAPACITY',v,flush=True)

